head.script:
// 컴포넌트·전역 이름 조회(엔진 캐시 → 이름 그대로 실행 → mf_ 접두사 붙여 다시, 없으면 받은 id 문자열 반환). 2026-11
scwin.__getObj = function(id) {
    if (typeof id !== 'string') return id;
    var W = WebSquare, C = W.idCache, U = W.idToUUID, F = function(k) { return new Function('return ' + k)(); };
    if (!W.strictMode) id = id.replace(/mf_/g, '');
    if (C[U[id]]) return C[U[id]];
    var r; try { r = F(id); } catch (e) {}
    if (r == undefined && W.strictMode) {
        var P = W.strictModeFrame.id + '_';
        var s = id.slice(0, 2) === 'G_' ? 'G_' + P + id.slice(2) : (id.slice(0, P.length) !== P ? P + id : id);
        s = s.replace(new RegExp('(' + P + '){2,}', 'g'), P);
        if (C[U[s]]) r = C[U[s]]; else { try { r = F(s); } catch (e) { r = id; } }
    }
    return r == undefined ? id : r;
};
scwin.init = function() {
    widgetContainer1.addWidgets([{
            id: "widget0",
            title: "위젯0",
            src: "widgetContainer_importWidgets_WPF-1746_(WSQ-2876)_content.xml",
            scope: true,
            x: 0,
            y: 0,
            unitWidth: 1,
            unitHeight: 1
        },
        {
            id: "widget1",
            title: "위젯1",
            src: "widgetContainer_importWidgets_WPF-1746_(WSQ-2876)_content.xml",
            scope: true,
            x: 1,
            y: 0,
            unitWidth: 1,
            unitHeight: 1
        },
        {
            id: "widget2",
            title: "위젯2",
            src: "widgetContainer_importWidgets_WPF-1746_(WSQ-2876)_content.xml",
            scope: true,
            x: 2,
            y: 0,
            unitWidth: 1,
            unitHeight: 1
        }
    ]);
    var jsonData1 = [{
            "col1": "aaa1",
            "col2": "bbb1",
            "col3": "ccc1"
        },
        {
            "col1": "aaa2",
            "col2": "bbb2",
            "col3": "ccc2"
        },
        {
            "col1": "aaa3",
            "col2": "bbb3",
            "col3": "ccc3"
        }
    ];
    var jsonData2 = [{
            "col1": "가나다1",
            "col2": "가가가1",
            "col3": "나나나1"
        },
        {
            "col1": "가나다2",
            "col2": "가가가2",
            "col3": "나나나2"
        },
        {
            "col1": "가나다3",
            "col2": "가가가3",
            "col3": "나나나3"
        }
    ];
    var jsonData3 = [{
            "col1": "11111",
            "col2": "22222",
            "col3": "44444"
        },
        {
            "col1": "11111",
            "col2": "22222",
            "col3": "55555"
        },
        {
            "col1": "11111",
            "col2": "33333",
            "col3": "66666"
        }
    ];
    scwin.__getObj($p.id+'widgetContainer1_widget0_content_dataList1').setJSON(jsonData1);
    scwin.__getObj($p.id+'widgetContainer1_widget1_content_dataList1').setJSON(jsonData2);
    scwin.__getObj($p.id+'widgetContainer1_widget2_content_dataList1').setJSON(jsonData3);
}
scwin.onwidgetload = function(id) {
    scwin.__getObj($p.id+'widgetContainer1_widget0_content_gridView').setCellColor(0, 0, "red");
    scwin.__getObj($p.id+'widgetContainer1_widget0_content_gridView').setRowColor(1, "red");
};
scwin.trigger1_onclick = function(e) {
    widgetContainer1.importWidgets(null, true);
};
scwin.__isShowLogNormal = function() {
    var err = WebSquare.logger.getErrorLog();
    return !err;
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
}
